                else if(stage=="revive_first" || stage=="revive_retry")
                {yield return Wait(()=>Local.GetComponent<PlayerDeath>().NearbyDowned()!=null,"client sees nearby Downed");var end=Time.realtimeSinceStartup+(stage=="revive_first"?1f:3.5f);while(Time.realtimeSinceStartup<end){var accepted=Local.HoldRevive(true);Log("hold queued="+accepted+" own="+Local.GetComponent<PlayerDeath>().State+" other="+Other.GetComponent<PlayerDeath>().State);yield return new WaitForSecondsRealtime(.1f);}Local.HoldRevive(false);yield return Wait(()=>Other.GetComponent<PlayerDeath>().State==(stage=="revive_first"?PlayerLife.Downed:PlayerLife.Alive),"revive release/commit replica");Ack(stage);}
                else if(stage=="prepare_r2"){yield return Leave();Profile(ClientId,"engineer","A1","A2","A3","B1","B2","B3");Ack(stage);}
                else if(stage=="marker_seen"){yield return Wait(()=>Other.GetComponent<NetworkClassActions>().State.Value.MarkerUntil>Role(Local).Now,"team marker");Check(Role(Other).Definition.Id=="explorer" && Role(Local).Definition.Id=="engineer","Explorer/Engineer replicate");Ack(stage);}
