                {yield return Wait(()=>WorldPlaceable.Active.Any(p=>p.PlayerBuilt && p.Definition.Item.Id=="wood_wall"),"wood wall replica");var target=WorldPlaceable.Active.First(p=>p.PlayerBuilt && p.Definition.Item.Id=="wood_wall").GetComponent<StructureMaintenance>();var end=Time.realtimeSinceStartup+(stage=="dismantle"?2.3f:1.8f);while(Time.realtimeSinceStartup<end){Local.GetComponent<NetworkClassActions>().Request(ClassAction.Building,true,target,default,(byte)(stage=="dismantle"?BuildingServiceKind.Dismantle:BuildingServiceKind.Repair));yield return new WaitForSecondsRealtime(.12f);}Local.GetComponent<NetworkClassActions>().Request(ClassAction.Building,false);Ack(stage);}
