                else if(stage=="leave_rehost"){yield return Leave();SelectRole("engineer");Ack(stage);}
                else if(stage=="prepare_r3"){yield return Leave();Profile(ClientId,"survivor","A1","A2","A3","C1","C2","C3");Ack(stage);}
                else if(stage=="quarry_seen"){yield return Wait(()=>Other.GetComponent<NetworkClassActions>().State.Value.QuarryUntil>Role(Local).Now,"Quarry replica");Check(Role(Other).Definition.Id=="hunter" && Role(Local).Definition.Id=="survivor","Hunter/Survivor replicate");Ack(stage);}
