        private static IEnumerator FourActors()
        {
            Phase="four-actor-simulation";Log("three simulated server actors; this is not four physical clients");
            var peers=new System.Collections.Generic.List<NetworkPlayer>();var origin=NetworkCreatureWorld.Active.World.Map.Spawn;var ids=new[]{"medic","engineer","explorer"};
            for(var i=0;i<3;i++)
            {var id=new string((char)('1'+i),32);Profile(id,ids[i]);var p=UnityEngine.Object.Instantiate(session.PlayerPrefab).GetComponent<NetworkPlayer>();typeof(NetworkPlayer).GetProperty("ProfileId").SetValue(p,id);p.GetComponent<PlayerClass>().Lock(id,ClassProfiles.Store.Read(id));p.GetComponent<PlayerDeath>().InitializeHome(origin);p.NetworkObject.Spawn();peers.Add(p);Move(p,origin+new Vector2(i+1,2));}
            Freeze();Move(Local,origin);Move(peers[0],origin+Vector2.right);Move(peers[1],origin+Vector2.right*2);Move(peers[2],origin+Vector2.up*2);Empty(peers[0]);Give(peers[0],"healing_salve");Local.Health.RestoreHealth(20);
            Check(NetworkPlayer.Active.Count==4 && NetworkPlayer.Active.Select(p=>Role(p).Definition.Id).Distinct().Count()==4,"four simulated actors retain four different classes");
            Check(peers[0].GetComponent<PlayerMedicine>().Begin(Local.Health) && Local.Health.Current==20+Mathf.RoundToInt(30*Role(Local).MedicineReceived),"simulated Medic ally Medicine baseline");
            var wall=Built("wood_wall",origin+new Vector2(3,1));wall.Health.ApplyDamage(50,true);wall.Health.RestoreCombatTime(0,0);var service=peers[1].GetComponent<PlayerBuildingService>();var end=Time.time+2.2f;
            while(Time.time<end){service.Hold(wall.GetComponent<StructureMaintenance>(),BuildingServiceKind.Repair,true);yield return null;}service.Hold(wall.GetComponent<StructureMaintenance>(),BuildingServiceKind.Repair,false);Check(wall.Health.Current==100,"simulated Engineer repairs shared structure");
            var down=peers[1].GetComponent<PlayerDeath>();peers[1].Health.ApplyDamage(10000,true);var helper=peers[0].GetComponent<PlayerDeath>();end=Time.time+4.3f;
            while(Time.time<end && down.State!=PlayerLife.Alive){down.ReceiveHold(helper,down.Revision,true);yield return null;}down.ReceiveHold(helper,down.Revision,false);Check(down.State==PlayerLife.Alive && peers[1].Health.Current==40,"simulated Medic baseline revive alongside two other classes");
            var before=System.GC.GetTotalMemory(false);var frame=Time.frameCount;var began=Time.realtimeSinceStartup;yield return new WaitForSecondsRealtime(3);var elapsed=Time.realtimeSinceStartup-began;Log("PERF four actors frames="+(Time.frameCount-frame)+" elapsed="+elapsed+" meanMs="+(1000*elapsed/Mathf.Max(1,Time.frameCount-frame))+" managedDelta="+(System.GC.GetTotalMemory(false)-before));
            Check(NetworkPlayer.Active.All(p=>Role(p).Locked) && peers.All(p=>!Role(p).Lock(p.ProfileId,ClassProfiles.Store.Read(p.ProfileId))),"four actor session locks reject replacement");yield return Shot("lan-four-actor-simulation");foreach(var p in peers)p.NetworkObject.Despawn();
        }
